from pathlib import Path
p=Path('src/App.tsx'); s=p.read_text()
old='''<div className="itemMeta"><span>{item.type}</span>{catalog!=='Equipment'&&<span>{catalog}</span>}{item.category&&<span>{item.category}</span>}<span>{item.cost}z</span>{item.martial&&<span>Martial</span>}{item.material&&<span>Material</span>}</div>{item.baseItem&&<p><strong>Base:</strong> {item.baseItem}</p>}{item.material&&<div className="materialBox"><span className="source">Natural Fantasy Material</span><p><strong>{item.material.name}</strong> · {item.material.nature}</p><p className="muted">{item.material.descriptorKind}{item.material.element?` · ${item.material.element}`:''}{item.material.function?` · ${item.material.function}`:''}</p></div>}{item.origin&&<p className="note"><strong>Origin:</strong> {item.origin}</p>}{item.type==='Weapon'&&<div className="stats"><b>{item.handedness}</b><b>{item.range}</b><b>{item.accuracy}{item.accuracyBonus?` +${item.accuracyBonus}`:''}</b><b>HR + {item.damage}</b><b>{item.damageType}</b></div>}{(item.type==='Armor'||item.type==='Shield')&&<div className="stats"><b>DEF {item.defense}</b><b>M.DEF {item.magicDefense}</b><b>Init {item.initiative&&item.initiative>0?'+':''}{item.initiative||0}</b></div>}{item.quality&&<p><strong>Quality / Customizations:</strong> {item.quality}</p>}<p className="attack">{item.effect}</p>{(item.breakdown?.length??0)>0&&<details><summary>Price / rule breakdown</summary>{(item.breakdown||[]).map((b,i)=><p className="note" key={i}>{b}</p>)}</details>'''
new='''<div className="itemArchiveMeta"><span className="itemTypeSeal">{item.type}</span>{catalog!=='Equipment'&&<span>{catalog}</span>}{item.category&&<span>{item.category}</span>}{item.martial&&<span>Martial</span>}{item.material&&<span>Material-bound</span>}<strong>{item.cost}z</strong></div>{item.baseItem&&<div className="itemBase"><span>Base pattern</span><strong>{item.baseItem}</strong></div>}{item.type==='Weapon'&&<div className="itemVitals"><div><span>Hands</span><strong>{item.handedness||'—'}</strong></div><div><span>Range</span><strong>{item.range||'—'}</strong></div><div><span>Accuracy</span><strong>{item.accuracy||'—'}{item.accuracyBonus?` +${item.accuracyBonus}`:''}</strong></div><div><span>Damage</span><strong>HR + {item.damage??'—'}</strong></div><div className={`damageSeal damage-${item.damageType||'physical'}`}><span>Type</span><strong>{item.damageType||'—'}</strong></div></div>}{(item.type==='Armor'||item.type==='Shield')&&<div className="itemVitals defensive"><div><span>DEF</span><strong>{item.defense??'—'}</strong></div><div><span>M.DEF</span><strong>{item.magicDefense??'—'}</strong></div><div><span>Initiative</span><strong>{item.initiative&&item.initiative>0?'+':''}{item.initiative||0}</strong></div></div>}{item.quality&&<div className="itemQuality"><span>Quality / Customizations</span><strong>{item.quality}</strong></div>}<div className="itemEffect"><span className="sectionLabel">Effect</span><p>{item.effect}</p></div>{item.material&&<div className="materialArchive"><div><span className="source">Natural Fantasy Material</span><h3>{item.material.name}</h3></div><span className="materialNature">{item.material.nature}</span><p>{item.material.descriptorKind}{item.material.element?` · ${item.material.element}`:''}{item.material.function?` · ${item.material.function}`:''}</p></div>}{item.origin&&<div className="itemProvenance"><span>Provenance</span><p>{item.origin}</p></div>}{(item.breakdown?.length??0)>0&&<details className="itemRules"><summary>Archive record · price & rules</summary><div className="lorePanel">{(item.breakdown||[]).map((b,i)=><p className="note" key={i}>{b}</p>)}</div></details>'''
if old not in s: raise SystemExit('item card block not found')
s=s.replace(old,new,1); p.write_text(s)
p=Path('src/styles.css'); s=p.read_text(); anchor='.itemMeta span {'
idx=s.find(anchor)
if idx<0: raise SystemExit('item css anchor missing')
css='''.itemArchiveMeta { display:flex; flex-wrap:wrap; align-items:center; gap:6px; margin:10px 0 13px; }\n.itemArchiveMeta span { border:1px solid #3e514c; background:#0a1818; color:#c9c3b3; padding:4px 8px; font-size:.72rem; text-transform:uppercase; letter-spacing:.06em; }\n.itemArchiveMeta .itemTypeSeal { border-color:var(--brass); color:var(--brass-bright); }\n.itemArchiveMeta strong { margin-left:auto; padding:5px 10px; border:1px solid rgba(195,167,108,.5); background:rgba(195,167,108,.09); color:var(--brass-bright); font-size:1.05rem; }\n.itemBase { display:flex; gap:10px; align-items:baseline; padding:7px 9px; margin-bottom:10px; border-left:2px solid #53655f; background:rgba(8,18,19,.62); } .itemBase span,.itemProvenance>span { color:#929f99; text-transform:uppercase; letter-spacing:.11em; font-size:.65rem; font-weight:800; }\n.itemVitals { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:5px; margin:11px 0 13px; } .itemVitals.defensive { grid-template-columns:repeat(3,minmax(0,1fr)); }\n.itemVitals>div { display:grid; align-content:center; min-height:61px; padding:7px; text-align:center; border:1px solid #3b504b; background:linear-gradient(180deg,#10201f,#091515); }\n.itemVitals span { color:#8f9d97; font-size:.63rem; text-transform:uppercase; letter-spacing:.1em; } .itemVitals strong { color:#ece3cf; font-size:.92rem; text-transform:capitalize; } .itemVitals .damageSeal { border-color:rgba(195,167,108,.45); } .damageSeal strong { color:var(--crystal-bright); }\n.itemQuality { display:grid; gap:3px; padding:10px 11px; margin:10px 0; border-left:3px solid var(--crystal); background:rgba(99,190,173,.07); } .itemQuality span { color:var(--crystal); font-size:.65rem; text-transform:uppercase; letter-spacing:.12em; } .itemQuality strong { color:#e3dece; font-weight:600; }\n.itemEffect { margin:12px 0; padding:11px 12px; border:1px solid #43544f; background:rgba(5,14,15,.66); } .itemEffect p { margin:4px 0 0; color:#e7dfcc; line-height:1.48; }\n.materialArchive { position:relative; display:grid; grid-template-columns:1fr auto; gap:3px 12px; margin:13px 0; padding:11px 12px; border:1px solid rgba(111,133,100,.55); border-left:3px solid var(--moss); background:linear-gradient(135deg,rgba(80,105,69,.13),rgba(7,17,16,.75)); } .materialArchive h3 { margin:2px 0 0; color:#d9d5bd; } .materialArchive p { grid-column:1/-1; margin:4px 0 0; color:#aeb9ad; } .materialNature { align-self:center; color:#b8c9a9; font-size:.72rem; text-transform:uppercase; letter-spacing:.08em; }\n.itemProvenance { margin:11px 0; padding:8px 10px; border-left:2px solid var(--brass); background:rgba(195,167,108,.055); } .itemProvenance p { margin:3px 0 0; color:#c9c3b4; }\n.itemRules { margin-top:13px; padding:8px 10px; border:1px solid #354944; background:rgba(6,15,16,.48); } .itemRules summary { color:#bdb397; }\n@media(max-width:760px){ .itemVitals{grid-template-columns:repeat(2,minmax(0,1fr));}.itemVitals.defensive{grid-template-columns:repeat(3,minmax(0,1fr));}.itemArchiveMeta strong{margin-left:0}.materialArchive{grid-template-columns:1fr}.materialArchive p{grid-column:1}.materialNature{justify-self:start} }\n\n'''
s=s[:idx]+css+s[idx:]; p.write_text(s)
